-- PostgreSQL schema for the current JPA entities.
-- IDs are VARCHAR because the entities use String IDs generated by Hibernate.
-- Image paths remain scalar strings; no attachment relationship is implied.
-- IF NOT EXISTS supports installations whose tables were created by Hibernate;
-- it does not retrofit constraints onto existing tables.

CREATE TABLE IF NOT EXISTS attach (
    id VARCHAR(255) PRIMARY KEY,
    origin_name VARCHAR(255),
    size BIGINT CHECK (size >= 0),
    type VARCHAR(255),
    path VARCHAR(255),
    duration BIGINT CHECK (duration >= 0),
    created_date TIMESTAMP(6) WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS location (
    id VARCHAR(255) PRIMARY KEY,
    latitude DOUBLE PRECISION CHECK (latitude BETWEEN -90 AND 90),
    longitude DOUBLE PRECISION CHECK (longitude BETWEEN -180 AND 180),
    region VARCHAR(255),
    district VARCHAR(255),
    street_address VARCHAR(255)
);

CREATE TABLE IF NOT EXISTS profile (
    id VARCHAR(255) PRIMARY KEY,
    name VARCHAR(255),
    surname VARCHAR(255),
    username VARCHAR(255),
    password VARCHAR(255),
    phone_number VARCHAR(255),
    status VARCHAR(255) DEFAULT 'ACTIVE'
        CHECK (status IN ('ACTIVE', 'BLOCKED', 'IN_REGISTRATION')),
    profile_image VARCHAR(255),
    district VARCHAR(255),
    mahalla VARCHAR(255),
    streak_days INTEGER DEFAULT 0 CHECK (streak_days >= 0),
    coin_balance INTEGER DEFAULT 0 CHECK (coin_balance >= 0),
    total_earned_coins INTEGER DEFAULT 0 CHECK (total_earned_coins >= 0),
    report_count INTEGER DEFAULT 0 CHECK (report_count >= 0),
    visible BOOLEAN DEFAULT TRUE,
    blocked BOOLEAN NOT NULL DEFAULT FALSE,
    last_report_date TIMESTAMP(6) WITHOUT TIME ZONE,
    created_date TIMESTAMP(6) WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    photo_id VARCHAR(255),
    CONSTRAINT uq_profile_username UNIQUE (username)
);

CREATE TABLE IF NOT EXISTS profile_role (
    id VARCHAR(255) PRIMARY KEY,
    profile_id VARCHAR(255),
    roles VARCHAR(255) CHECK (roles IN ('ROLE_USER', 'ROLE_ADMIN')),
    created_date TIMESTAMP(6) WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_profile_role_profile FOREIGN KEY (profile_id) REFERENCES profile(id),
    CONSTRAINT uq_profile_role UNIQUE (profile_id, roles)
);

CREATE TABLE IF NOT EXISTS reward (
    id VARCHAR(255) PRIMARY KEY,
    title VARCHAR(255),
    description VARCHAR(255),
    coin_price INTEGER CHECK (coin_price > 0),
    provider_name VARCHAR(255),
    image_url VARCHAR(255),
    quantity INTEGER DEFAULT 0 CHECK (quantity >= 0),
    is_active BOOLEAN DEFAULT TRUE,
    created_date_time TIMESTAMP(6) WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS profile_reward (
    id VARCHAR(255) PRIMARY KEY,
    profile_id VARCHAR(255) NOT NULL,
    reward_id VARCHAR(255) NOT NULL,
    quantity INTEGER CHECK (quantity > 0),
    coins_spent INTEGER CHECK (coins_spent > 0),
    created_date TIMESTAMP(6) WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    -- Keep purchases and their referenced rewards/profiles for history.
    CONSTRAINT fk_profile_reward_profile FOREIGN KEY (profile_id) REFERENCES profile(id),
    CONSTRAINT fk_profile_reward_reward FOREIGN KEY (reward_id) REFERENCES reward(id)
);

CREATE TABLE IF NOT EXISTS coin_transaction (
    id VARCHAR(255) PRIMARY KEY,
    profile_id VARCHAR(255) NOT NULL,
    amount INTEGER CHECK (amount > 0),
    coin_type VARCHAR(255) NOT NULL CHECK (coin_type IN ('EARN', 'SPEND', 'BONUS')),
    description VARCHAR(255),
    created_date TIMESTAMP(6) WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_coin_transaction_profile FOREIGN KEY (profile_id) REFERENCES profile(id)
);

CREATE TABLE IF NOT EXISTS campaigns (
    id VARCHAR(255) PRIMARY KEY,
    title VARCHAR(255),
    description TEXT,
    start_date VARCHAR(255),
    end_date VARCHAR(255),
    attendees_count INTEGER DEFAULT 0 CHECK (attendees_count >= 0),
    reward_coins INTEGER DEFAULT 0 CHECK (reward_coins >= 0),
    company_type VARCHAR(255) CHECK (company_type IN ('GOVERNMENT', 'PRIVATE', 'COMMUNITY')),
    location_id VARCHAR(255),
    created_date TIMESTAMP(6) WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_campaigns_location FOREIGN KEY (location_id) REFERENCES location(id),
    CONSTRAINT uq_campaigns_location UNIQUE (location_id)
);

CREATE TABLE IF NOT EXISTS waste_report (
    id VARCHAR(255) PRIMARY KEY,
    before_image_url VARCHAR(255) NOT NULL,
    after_image_url VARCHAR(255),
    is_live_camera BOOLEAN DEFAULT TRUE,
    captured_date TIMESTAMP(6) WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    location_id VARCHAR(255) NOT NULL,
    waste_type VARCHAR(255) NOT NULL
        CHECK (waste_type IN ('PLASTIC', 'ILLEGAL_DUMP', 'WATER', 'AIR', 'ELECTRONIC', 'OTHER')),
    severity_level VARCHAR(255) NOT NULL,
    description TEXT,
    report_action VARCHAR(255) NOT NULL CHECK (report_action IN ('CLEAN_MYSELF', 'SEND_TO_OTHERS')),
    reporter_reward_coins INTEGER DEFAULT 0 CHECK (reporter_reward_coins >= 0),
    cleaner_reward_coins INTEGER DEFAULT 0 CHECK (cleaner_reward_coins >= 0),
    report_status VARCHAR(255) NOT NULL DEFAULT 'PENDING'
        CHECK (report_status IN ('PENDING', 'IN_PROGRESS', 'RESOLVED', 'REJECTED')),
    reporter_id VARCHAR(255) NOT NULL,
    cleaner_id VARCHAR(255),
    clean_period DOUBLE PRECISION CHECK (clean_period > 0),
    confidence_score INTEGER CHECK (confidence_score BETWEEN 0 AND 100),
    ai_reasoning TEXT,
    ai_review_status VARCHAR(255) DEFAULT 'PENDING'
        CHECK (ai_review_status IN ('PENDING', 'COMPLETED', 'FAILED')),
    ai_waste_present BOOLEAN,
    ai_same_location BOOLEAN,
    ai_waste_cleared BOOLEAN,
    ai_detected_anchors TEXT,
    ai_reviewed_at TIMESTAMP(6) WITHOUT TIME ZONE,
    ai_reward_granted BOOLEAN DEFAULT FALSE,
    created_date TIMESTAMP(6) WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    -- Same name as the existing repeatable severity migration.
    CONSTRAINT waste_report_severity_level_check
        CHECK (severity_level IN ('LOW', 'MEDIUM', 'HIGH', 'UNDER_REVIEW')),
    CONSTRAINT fk_waste_report_location FOREIGN KEY (location_id) REFERENCES location(id),
    CONSTRAINT fk_waste_report_reporter FOREIGN KEY (reporter_id) REFERENCES profile(id),
    CONSTRAINT fk_waste_report_cleaner FOREIGN KEY (cleaner_id) REFERENCES profile(id),
    CONSTRAINT uq_waste_report_location UNIQUE (location_id)
);

-- Catalog identity and the application's main list/history queries.
CREATE UNIQUE INDEX IF NOT EXISTS uq_reward_title_provider
    ON reward (LOWER(TRIM(title)), LOWER(TRIM(provider_name)));
CREATE INDEX IF NOT EXISTS idx_profile_ranking ON profile (total_earned_coins DESC);
CREATE INDEX IF NOT EXISTS idx_attach_created ON attach (created_date DESC);
CREATE INDEX IF NOT EXISTS idx_reward_catalog
    ON reward (created_date_time DESC, id DESC) WHERE is_active IS TRUE AND quantity > 0;
CREATE INDEX IF NOT EXISTS idx_profile_reward_history ON profile_reward (profile_id, created_date DESC);
CREATE INDEX IF NOT EXISTS idx_profile_reward_reward ON profile_reward (reward_id);
CREATE INDEX IF NOT EXISTS idx_coin_transaction_history ON coin_transaction (profile_id, created_date DESC);
CREATE INDEX IF NOT EXISTS idx_waste_report_status ON waste_report (report_status, created_date DESC);
CREATE INDEX IF NOT EXISTS idx_waste_report_reporter ON waste_report (reporter_id, created_date DESC);
CREATE INDEX IF NOT EXISTS idx_waste_report_cleaner ON waste_report (cleaner_id, created_date DESC);
